x_comment(x_oxygenatedBloodFlowsFromAndTo,"Indicates that oxygenated blood flows from arg1 to arg2.  For example,\n(oxygenatedBloodFlowsFromAndTo Lungs LeftAtrium) means that oxygenated blood flows\nfrom the lungs to the left ventricle.") :- x_cid(a65b1338687561).
