x_comment(x_bloodFlowsFromAndTo,"Indicates that blood flows from arg1 to arg2.  \nThis relation is asymmetric because blood flow has direction.\nFor example, (bloodFlowsFromAndTo RightVentricle Lungs) means that blood flows from the\nright ventricle to the lungs.") :- x_cid(a65b1338687563).
