x_comment('x_biologicTransfer-Oxygen',"Indicates the transfer of carbon dioxide from one instance of #$OrganicMaterial to another.\nFor example: (biologicTransfer-Oxygen Lungs Blood) represents the transfer of carbon dioxide\nfrom Lungs to Blood.  Arguments can be instances of #$AnimalBodyPart (e.g. Lungs, Blood) or, more\ngenerally, #$OrganicMaterial (e.g. the atmosphere).") :- x_cid(a65b1338687564).
xc_microtheory(a65b1338687564,x_AnimalPhysiologyMt).
xc_source_file(a65b1338687564,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/AnimalPhysiologyMt.krf').
