x_comment('x_biologicTransfer-CarbonDioxide',"Indicates the transfer of carbon dioxide from one instance of #$OrganicMaterial to another.\nFor example: (biologicTransfer-CarbonDioxide Blood Lungs) represents the transfer of carbon dioxide\nfrom Blood to Lungs.  Arguments can be instances of #$AnimalBodyPart (e.g. Blood, Lungs) or, more\ngenerally, #$OrganicMaterial (e.g. the atmosphere).  See also #$biologicTransfer-Oxygen") :- x_cid(a65b1338687565).
xc_microtheory(a65b1338687565,x_AnimalPhysiologyMt).
xc_source_file(a65b1338687565,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/AnimalPhysiologyMt.krf').
