xc_mapping_rows(a65b1338687565,[]).
x_comment('x_biologicTransfer-Generic',"Indicates the general biologic transfer of something from arg1 to arg2.  This covers\nthings like waste transferring from cells to blood, nutrients transferring from blood\nto cells, etc.  It can also mean the transfer of blood from one area of the body to another (see\n#$bloodFlowsFromAndTo).  When possible, use an existing (or define a new) specialization of this\nrelation.") :- x_cid(a65b1338687566).
xc_microtheory(a65b1338687566,x_AnimalPhysiologyMt).
xc_source_file(a65b1338687566,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/AnimalPhysiologyMt.krf').
