x_comment('x_Astigmatism-EyeDisorder',"An instance of #$PhysiologicalConditionType and a specialization of #$EyeDisorder.  Astigmatism is a defect in which vision is blurry because the focal point of the eye varies around its circumference. In regular astigmatism, the principal meridians - planes of highest and lowest refractive power - are perpendicular.  If these planes are not perpendicular, the condition is termed irregular astigmatism.   #$Astigmatism-EyeDisorder can often be corrected with #$Eyewear-Corrective or with #$RefractiveEyeSurgery.  ") :- x_cid(a65b133868758f).
xc_microtheory(a65b133868758f,x_AnimalPhysiologyMt).
