x_comment(x_ExternalAnimalBodyRegionType,"A #$SecondOrderCollection and a specialization of #$OrganismConstituentType.  Each instance of #$ExternalAnimalBodyRegionType is a specialization of #$AnimalBodyRegion whose instances are, under normal circumstances, at least partially on the outside surface of animal.  Instances include #$Head-AnimalBodyPart, #$Wing-AnimalBodyPart,and #$UpperBody-Human.  Non-instances include #$Heart, #$Brain, and #$Bone-BodyPart.  Borderline cases include #$Tooth and #$Eardrum.") :- x_cid(a65b1338687595).
