x_comment(x_contactToxicityOfTypeFor,"A #$TernaryPredicate that relates a specialization of #$PartiallyTangible to an #$OrganismClassificationType to a #$Toxicity.  (#$contactToxicityOfTypeFor PT-TYPE ORG-TYPE TOXICITY) means that the contact toxicity of PT-TYPE for ORG-TYPE is TOXICITY.  For example, (#$contactToxicityOfTypeFor #$SulfuricAcid #$HomoSapiens #$ExtremelyToxic) means that sulfuric acid is extremely toxic to humans when contacted.") :- x_cid(a65b13386875cf).
